/*
 * mini_regex.c
 *
 * A small regular expression engine for C. generated by GPT-5.6 Luna .
 *
 * Supported:
 *
 *   literal       abc
 *   .             any character
 *
 *   ^             beginning of string
 *   $             end of string
 *
 *   []            character class
 *   [a-z]         character range
 *   [^a-z]        negated character class
 *
 *   \d            digit
 *   \s            whitespace
 *   \w            word character
 *
 *   *             0 or more
 *   +             1 or more
 *   ?             0 or 1
 *
 *   {n}            exactly n
 *   {n,m}          n through m
 *   {n,}           n or more
 *
 *   |              alternation
 *   (...)           group
 *
 *   \x             escaped literal x
 *
 * Not supported:
 *
 *   capturing groups / back references
 *   lookahead / lookbehind
 *   lazy quantifiers
 *   Unicode character classes
 *
 * Encoding:
 *
 *   This implementation operates on bytes.
 *   UTF-8 characters are NOT treated as individual characters.
 *
 * Build test:
 *
 *   gcc -DTEST_REGEX -o mini_regex mini_regex.c
 *
 * MSVC:
 *
 *   cl /DTEST_REGEX mini_regex.c
 */

#include "mini_regex.h"


/* ============================================================
 * Configuration
 * ============================================================ */

#define RX_MAX_REPEAT 1000000


/* ============================================================
 * AST node
 * ============================================================ */

typedef enum {
    RX_EMPTY,
    RX_LITERAL,
    RX_ANY,
    RX_CLASS,
    RX_DIGIT,
    RX_SPACE,
    RX_WORD,

    RX_CONCAT,
    RX_ALT,

    RX_REPEAT
} RxType;


typedef struct RxNode RxNode;
struct RxNode {
    RxType type;

    union {

        unsigned char literal;

        struct {
            unsigned char table[256];
        } cls;

        struct {
            RxNode *left;
            RxNode *right;
        } binary;

        struct {
            RxNode *child;
            int min;
            int max;
        } repeat;
    } u;
};


/* ============================================================
 * Parser
 * ============================================================ */

typedef struct {
    const char *p;
    const char *error;
} Parser;


/* ------------------------------------------------------------
 * Memory management
 * ------------------------------------------------------------ */

static RxNode *node_new(RxType type)
{
    RxNode *n = (RxNode *)calloc(1, sizeof(RxNode));

    if (!n)
        return NULL;

    n->type = type;

    return n;
}


static void node_free(RxNode *n)
{
    if (!n)
        return;

    switch (n->type) {

    case RX_CONCAT:
    case RX_ALT:
        node_free(n->u.binary.left);
        node_free(n->u.binary.right);
        break;

    case RX_REPEAT:
        node_free(n->u.repeat.child);
        break;

    default:
        break;
    }

    free(n);
}


/* ------------------------------------------------------------
 * Parser helpers
 * ------------------------------------------------------------ */

static int parser_error(Parser *ps, const char *msg)
{
    ps->error = msg;
    return 0;
}


/* ============================================================
 * Character class
 * ============================================================ */

static RxNode *parse_class(Parser *ps)
{
    RxNode *n;
    int negated = 0;

    n = node_new(RX_CLASS);

    if (!n) {
        parser_error(ps, "out of memory");
        return NULL;
    }

    if (*ps->p == '^') {
        negated = 1;
        ps->p++;
    }

    if (*ps->p == ']') {
        node_free(n);
        parser_error(ps, "empty character class");
        return NULL;
    }

    while (*ps->p && *ps->p != ']') {

        unsigned char first;
        unsigned char last;

        /*
         * Parse an escaped character or predefined class.
         */
        if (*ps->p == '\\') {

            ps->p++;

            if (!*ps->p) {
                node_free(n);
                parser_error(ps, "unterminated escape");
                return NULL;
            }

            switch (*ps->p) {

            case 'd':
                for (int c = '0'; c <= '9'; c++)
                    n->u.cls.table[c] = 1;
                ps->p++;
                continue;

            case 's':
                n->u.cls.table[' ']  = 1;
                n->u.cls.table['\t'] = 1;
                n->u.cls.table['\r'] = 1;
                n->u.cls.table['\n'] = 1;
                n->u.cls.table['\v'] = 1;
                n->u.cls.table['\f'] = 1;
                ps->p++;
                continue;

            case 'w':
                for (int c = '0'; c <= '9'; c++)
                    n->u.cls.table[c] = 1;

                for (int c = 'a'; c <= 'z'; c++)
                    n->u.cls.table[c] = 1;

                for (int c = 'A'; c <= 'Z'; c++)
                    n->u.cls.table[c] = 1;

                n->u.cls.table['_'] = 1;

                ps->p++;
                continue;

            default:
                first = (unsigned char)*ps->p++;
                break;
            }

        } else {
            first = (unsigned char)*ps->p++;
        }

        /*
         * Parse a character range such as a-z.
         */
        if (*ps->p == '-' &&
            ps->p[1] != '\0' &&
            ps->p[1] != ']') {

            ps->p++;

            if (*ps->p == '\\') {

                ps->p++;

                if (!*ps->p) {
                    node_free(n);
                    parser_error(ps, "unterminated range");
                    return NULL;
                }

                last = (unsigned char)*ps->p++;

            } else {
                last = (unsigned char)*ps->p++;
            }

            if (first > last) {
                node_free(n);
                parser_error(ps, "invalid character range");
                return NULL;
            }

            for (int c = first; c <= last; c++)
                n->u.cls.table[c] = 1;

        } else {
            n->u.cls.table[first] = 1;
        }
    }

    if (*ps->p != ']') {
        node_free(n);
        parser_error(ps, "unterminated character class");
        return NULL;
    }

    ps->p++;

    /*
     * Invert the character table for a negated class such as [^0-9].
     */
    if (negated) {
        for (int c = 0; c < 256; c++)
            n->u.cls.table[c] =
                !n->u.cls.table[c];
    }

    return n;
}


/* ============================================================
 * Atom
 *
 * atom:
 *
 *   literal
 *   .
 *   [...]
 *   (...)
 * ============================================================ */

static RxNode *parse_alt(Parser *ps);


/*
 * Parse a single regex atom.
 */
static RxNode *parse_atom(Parser *ps)
{
    RxNode *n;

    if (*ps->p == '\0') {
        return NULL;
    }

    /*
     * Parse a group.
     */
    if (*ps->p == '(') {

        ps->p++;

        n = parse_alt(ps);

        if (!n)
            return NULL;

        if (*ps->p != ')') {
            node_free(n);
            parser_error(ps, "missing ')'");
            return NULL;
        }

        ps->p++;

        return n;
    }

    /*
     * Parse a character class.
     */
    if (*ps->p == '[') {
        ps->p++;
        return parse_class(ps);
    }

    /*
     * Match any character.
     */
    if (*ps->p == '.') {
        ps->p++;

        n = node_new(RX_ANY);

        if (!n)
            parser_error(ps, "out of memory");

        return n;
    }

    /*
     * Parse an escape sequence.
     */
    if (*ps->p == '\\') {

        ps->p++;

        if (!*ps->p) {
            parser_error(ps, "unterminated escape");
            return NULL;
        }

        switch (*ps->p) {

        case 'd':
            n = node_new(RX_DIGIT);
            ps->p++;
            break;

        case 's':
            n = node_new(RX_SPACE);
            ps->p++;
            break;

        case 'w':
            n = node_new(RX_WORD);
            ps->p++;
            break;

        default:
            n = node_new(RX_LITERAL);

            if (n)
                n->u.literal =
                    (unsigned char)*ps->p;

            ps->p++;
            break;
        }

        if (!n)
            parser_error(ps, "out of memory");

        return n;
    }

    /*
     * Anchors and alternation are handled by the higher-level parser.
     */
    if (*ps->p == '^' ||
        *ps->p == '$' ||
        *ps->p == '|' ||
        *ps->p == ')') {

        return NULL;
    }

    /*
     * Parse a literal character.
     */
    n = node_new(RX_LITERAL);

    if (!n) {
        parser_error(ps, "out of memory");
        return NULL;
    }

    n->u.literal =
        (unsigned char)*ps->p++;

    return n;
}


/* ============================================================
 * Quantifier
 *
 * atom (* | + | ? | {n} | {n,m} | {n,})?
 * ============================================================ */

/*
 * Parse an atom followed by an optional quantifier.
 */
static RxNode *parse_quantified_atom(Parser *ps)
{
    RxNode *atom;
    RxNode *n;

    atom = parse_atom(ps);

    if (!atom)
        return NULL;

    /*
     * Zero or more.
     */
    if (*ps->p == '*') {

        ps->p++;

        n = node_new(RX_REPEAT);

        if (!n) {
            node_free(atom);
            parser_error(ps, "out of memory");
            return NULL;
        }

        n->u.repeat.child = atom;
        n->u.repeat.min = 0;
        n->u.repeat.max = RX_MAX_REPEAT;

        return n;
    }

    /*
     * One or more.
     */
    if (*ps->p == '+') {

        ps->p++;

        n = node_new(RX_REPEAT);

        if (!n) {
            node_free(atom);
            parser_error(ps, "out of memory");
            return NULL;
        }

        n->u.repeat.child = atom;
        n->u.repeat.min = 1;
        n->u.repeat.max = RX_MAX_REPEAT;

        return n;
    }

    /*
     * Zero or one.
     */
    if (*ps->p == '?') {

        ps->p++;

        n = node_new(RX_REPEAT);

        if (!n) {
            node_free(atom);
            parser_error(ps, "out of memory");
            return NULL;
        }

        n->u.repeat.child = atom;
        n->u.repeat.min = 0;
        n->u.repeat.max = 1;

        return n;
    }

    /*
     * Parse {n}, {n,m}, or {n,}.
     */
    if (*ps->p == '{') {

        const char *start;
        long min = 0;
        long max = 0;

        ps->p++;

        start = ps->p;

        while (isdigit((unsigned char)*ps->p)) {
            min = min * 10 + (*ps->p - '0');

            if (min > RX_MAX_REPEAT) {
                node_free(atom);
                parser_error(ps, "repeat count too large");
                return NULL;
            }

            ps->p++;
        }

        if (ps->p == start) {
            node_free(atom);
            parser_error(ps, "invalid repeat");
            return NULL;
        }

        /*
         * Exact repetition: {n}
         */
        if (*ps->p == '}') {

            ps->p++;

            max = min;
        }

        /*
         * Range repetition: {n,m} or {n,}
         */
        else if (*ps->p == ',') {

            ps->p++;

            /*
             * Open-ended repetition: {n,}
             */
            if (*ps->p == '}') {

                ps->p++;

                max = RX_MAX_REPEAT;

            } else {

                const char *max_start = ps->p;

                max = 0;

                while (isdigit((unsigned char)*ps->p)) {

                    max = max * 10 +
                          (*ps->p - '0');

                    if (max > RX_MAX_REPEAT) {
                        node_free(atom);
                        parser_error(
                            ps,
                            "repeat count too large"
                        );
                        return NULL;
                    }

                    ps->p++;
                }

                if (ps->p == max_start ||
                    *ps->p != '}') {

                    node_free(atom);
                    parser_error(
                        ps,
                        "invalid repeat"
                    );
                    return NULL;
                }

                ps->p++;

                if (min > max) {
                    node_free(atom);
                    parser_error(
                        ps,
                        "min repeat greater than max"
                    );
                    return NULL;
                }
            }
        }

        else {
            node_free(atom);
            parser_error(
                ps,
                "invalid repeat syntax"
            );
            return NULL;
        }

        n = node_new(RX_REPEAT);

        if (!n) {
            node_free(atom);
            parser_error(ps, "out of memory");
            return NULL;
        }

        n->u.repeat.child = atom;
        n->u.repeat.min = (int)min;
        n->u.repeat.max = (int)max;

        return n;
    }

    return atom;
}


/* ============================================================
 * Concatenation
 *
 * Examples:
 *
 *   abc
 *   ab[0-9]+
 * ============================================================ */

/*
 * Parse a sequence of adjacent atoms.
 */
static RxNode *parse_concat(Parser *ps)
{
    RxNode *root = NULL;

    while (*ps->p &&
           *ps->p != ')' &&
           *ps->p != '|') {

        RxNode *n;

        /*
         * Handle the beginning-of-string anchor.
         */
        if (*ps->p == '^') {

            /*
             * The anchor is only meaningful at the beginning
             * of the complete pattern.
             */
            ps->p++;
            continue;
        }

        /*
         * Handle the end-of-string anchor.
         */
        if (*ps->p == '$') {

            /*
             * The anchor is handled by the top-level parser.
             */
            break;
        }

        n = parse_quantified_atom(ps);

        if (!n) {
            if (ps->error)
                goto fail;

            break;
        }

        if (!root) {
            root = n;
        } else {
            RxNode *cat = node_new(RX_CONCAT);

            if (!cat) {
                node_free(n);
                goto fail;
            }

            cat->u.binary.left = root;
            cat->u.binary.right = n;

            root = cat;
        }
    }

    if (!root) {

        /*
         * Represent an empty sequence, for example an empty group.
         */
        root = node_new(RX_EMPTY);

        if (!root)
            parser_error(ps, "out of memory");
    }

    return root;

fail:

    node_free(root);

    if (!ps->error)
        parser_error(ps, "out of memory");

    return NULL;
}


/* ============================================================
 * Alternation
 *
 * Examples:
 *
 *   a|b
 *   foo|bar
 *   (abc|def)
 * ============================================================ */

/*
 * Parse one or more alternatives separated by '|'.
 */
static RxNode *parse_alt(Parser *ps)
{
    RxNode *left;

    left = parse_concat(ps);

    if (!left)
        return NULL;

    while (*ps->p == '|') {

        RxNode *right;
        RxNode *alt;

        ps->p++;

        right = parse_concat(ps);

        if (!right) {
            node_free(left);
            return NULL;
        }

        alt = node_new(RX_ALT);

        if (!alt) {
            node_free(left);
            node_free(right);
            parser_error(ps, "out of memory");
            return NULL;
        }

        alt->u.binary.left = left;
        alt->u.binary.right = right;

        left = alt;
    }

    return left;
}


/* ============================================================
 * Regex object
 * ============================================================ */

typedef struct {

    RxNode *root;

    int anchored_begin;
    int anchored_end;

} Regex;


/* ------------------------------------------------------------
 * Compile
 * ------------------------------------------------------------ */

/*
 * Parse and compile a regex pattern into an AST.
 */
static Regex *rx_compile(
    const char *pattern,
    const char **error
)
{
    Parser ps;
    Regex *re;

    ps.p = pattern;
    ps.error = NULL;

    re = (Regex *)calloc(1, sizeof(Regex));

    if (!re) {
        if (error)
            *error = "out of memory";
        return NULL;
    }

    /*
     * Detect the beginning-of-string anchor.
     */
    if (*ps.p == '^') {
        re->anchored_begin = 1;
        ps.p++;
    }

    re->root = parse_alt(&ps);

    if (!re->root) {
        free(re);

        if (error)
            *error = ps.error;

        return NULL;
    }

    /*
     * Detect the end-of-string anchor.
     */
    if (*ps.p == '$') {
        re->anchored_end = 1;
        ps.p++;
    }

    /*
     * The complete pattern must have been consumed.
     */
    if (*ps.p != '\0') {

        node_free(re->root);
        free(re);

        if (error)
            *error = ps.error ?
                ps.error :
                "unexpected character";

        return NULL;
    }

    if (error)
        *error = NULL;

    return re;
}


/* ============================================================
 * Matcher
 * ============================================================ */

typedef struct {
    const char *text;
} MatchContext;


/*
 * Match a node against the input string.
 *
 * On success, the callback receives the position immediately
 * after the matched portion.
 *
 * The callback-based design is used to support backtracking.
 */
typedef int (*MatchCallback)(
    const char *position,
    void *userdata
);


static int match_node(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
);


/* ------------------------------------------------------------
 * Basic atom matching
 * ------------------------------------------------------------ */

static int match_basic(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
)
{
    unsigned char c;

    switch (n->type) {

    case RX_EMPTY:
        return callback(text, userdata);

    case RX_LITERAL:

        if (*text &&
            (unsigned char)*text ==
            n->u.literal) {

            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    case RX_ANY:

        if (*text) {
            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    case RX_CLASS:

        if (*text &&
            n->u.cls.table[
                (unsigned char)*text]) {

            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    case RX_DIGIT:

        if (*text &&
            isdigit((unsigned char)*text)) {

            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    case RX_SPACE:

        if (*text &&
            isspace((unsigned char)*text)) {

            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    case RX_WORD:

        if (*text &&
            (isalnum((unsigned char)*text) ||
             *text == '_')) {

            return callback(
                text + 1,
                userdata
            );
        }

        return 0;

    default:
        return 0;
    }
}


/* ------------------------------------------------------------
 * Concatenation
 * ------------------------------------------------------------ */

typedef struct {
    RxNode *right;
    MatchCallback callback;
    void *userdata;
} ConcatContext;


/*
 * Continue matching with the right-hand side
 * after the left-hand side has matched.
 */
static int concat_callback(
    const char *position,
    void *userdata
)
{
    ConcatContext *ctx =
        (ConcatContext *)userdata;

    return match_node(
        ctx->right,
        position,
        ctx->callback,
        ctx->userdata
    );
}


/*
 * Match two concatenated nodes.
 */
static int match_concat(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
)
{
    ConcatContext ctx;

    ctx.right = n->u.binary.right;
    ctx.callback = callback;
    ctx.userdata = userdata;

    return match_node(
        n->u.binary.left,
        text,
        concat_callback,
        &ctx
    );
}


/* ------------------------------------------------------------
 * Alternation
 * ------------------------------------------------------------ */

/*
 * Try the left alternative first.
 * If it fails, try the right alternative.
 */
static int match_alt(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
)
{
    if (match_node(
            n->u.binary.left,
            text,
            callback,
            userdata)) {

        return 1;
    }

    return match_node(
        n->u.binary.right,
        text,
        callback,
        userdata
    );
}


/* ------------------------------------------------------------
 * Repetition
 * ------------------------------------------------------------ */

typedef struct {
    RxNode *parent;
    const char *position;
    int count;

    MatchCallback callback;
    void *userdata;
} RepeatContext;


