/*
 * State used while processing a repetition.
 */
typedef struct {
    RxNode *child;
    int min;
    int max;
    int count;

    const char *old_position;

    MatchCallback callback;
    void *userdata;
} RepeatState;


/*
 * Continue processing a repetition after one child match.
 */
static int repeat_after_child(
    const char *position,
    void *userdata
)
{
    RepeatState *state =
        (RepeatState *)userdata;

    /*
     * Prevent an infinite loop if the repeated child
     * consumes no input.
     */
    if (position == state->old_position) {

        if (state->count + 1 >= state->min)
            return state->callback(
                position,
                state->userdata
            );

        return 0;
    }

    /*
     * Try to consume another repetition.
     */
    if (state->count + 1 < state->max) {

        RepeatState next;

        next.child = state->child;
        next.min = state->min;
        next.max = state->max;
        next.count = state->count + 1;

        next.old_position = position;

        next.callback = state->callback;
        next.userdata = state->userdata;

        /*
         * Greedily consume another repetition.
         */
        if (match_node(
                state->child,
                position,
                repeat_after_child,
                &next)) {

            return 1;
        }
    }

    /*
     * Stop at the current repetition count.
     */
    if (state->count + 1 >= state->min) {

        if (state->callback(
                position,
                state->userdata)) {

            return 1;
        }
    }

    return 0;
}


/*
 * Match a repeated expression.
 */
static int match_repeat(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
)
{
    int min = n->u.repeat.min;
    int max = n->u.repeat.max;

    /*
     * Zero repetitions are allowed.
     */
    if (min == 0) {

        /*
         * Greedily try to consume the child first.
         */
        if (max > 0) {

            RepeatState state;

            state.child =
                n->u.repeat.child;

            state.min = min;
            state.max = max;
            state.count = 0;

            state.old_position = text;

            state.callback = callback;
            state.userdata = userdata;

            if (match_node(
                    state.child,
                    text,
                    repeat_after_child,
                    &state)) {

                return 1;
            }
        }

        /*
         * Fall back to zero repetitions.
         */
        return callback(text, userdata);
    }

    /*
     * At least one repetition is required.
     */
    {
        RepeatState state;

        state.child =
            n->u.repeat.child;

        state.min = min;
        state.max = max;
        state.count = 0;

        state.old_position = text;

        state.callback = callback;
        state.userdata = userdata;

        return match_node(
            state.child,
            text,
            repeat_after_child,
            &state
        );
    }
}


/* ------------------------------------------------------------
 * Main matcher
 * ------------------------------------------------------------ */

static int match_node(
    RxNode *n,
    const char *text,
    MatchCallback callback,
    void *userdata
)
{
    if (!n)
        return 0;

    switch (n->type) {

    case RX_EMPTY:
    case RX_LITERAL:
    case RX_ANY:
    case RX_CLASS:
    case RX_DIGIT:
    case RX_SPACE:
    case RX_WORD:

        return match_basic(
            n,
            text,
            callback,
            userdata
        );

    case RX_CONCAT:

        return match_concat(
            n,
            text,
            callback,
            userdata
        );

    case RX_ALT:

        return match_alt(
            n,
            text,
            callback,
            userdata
        );

    case RX_REPEAT:

        return match_repeat(
            n,
            text,
            callback,
            userdata
        );

    default:
        return 0;
    }
}


/* ============================================================
 * Final callback
 * ============================================================ */

typedef struct {
    int anchored_end;
} FinalContext;


/*
 * Check whether a successful match satisfies the
 * end-of-string requirement.
 */
static int final_callback(
    const char *position,
    void *userdata
)
{
    FinalContext *ctx =
        (FinalContext *)userdata;

    if (ctx->anchored_end)
        return *position == '\0';

    return 1;
}


/* ============================================================
 * Public API
 * ============================================================ */

/*
 * Match the entire input string against the pattern.
 */
int rx_match(
    const char *pattern,
    const char *text
)
{
    const char *error;
    Regex *re;

    FinalContext ctx;

    re = rx_compile(pattern, &error);

    if (!re)
        return 0;

    /*
     * rx_match requires the complete input string to match.
     */
    ctx.anchored_end = 1;

    /*
     * The beginning anchor has already been removed
     * during compilation.
     */
    {
        int result =
            match_node(
                re->root,
                text,
                final_callback,
                &ctx
            );

        node_free(re->root);
        free(re);

        return result;
    }
}


/*
 * Search for a matching substring within the input string.
 */
int rx_search(
    const char *pattern,
    const char *text
)
{
    const char *error;
    Regex *re;

    FinalContext ctx;

    re = rx_compile(pattern, &error);

    if (!re)
        return 0;

    ctx.anchored_end =
        re->anchored_end;

    /*
     * If the pattern is anchored at the beginning,
     * only test the beginning of the input.
     */
    if (re->anchored_begin) {

        int result =
            match_node(
                re->root,
                text,
                final_callback,
                &ctx
            );

        node_free(re->root);
        free(re);

        return result;
    }

    /*
     * Otherwise, try matching from every position.
     */
    {
        const char *p = text;

        while (1) {

            if (match_node(
                    re->root,
                    p,
                    final_callback,
                    &ctx)) {

                node_free(re->root);
                free(re);

                return 1;
            }

            if (*p == '\0')
                break;

            p++;
        }
    }

    node_free(re->root);
    free(re);

    return 0;
}


/* ============================================================
 * Test
 * ============================================================ */

#ifdef TEST_REGEX

static void test(
    const char *pattern,
    const char *text
)
{
    printf(
        "%-25s %-25s => %s\n",
        pattern,
        text,
        rx_search(pattern, text)
            ? "MATCH"
            : "NO MATCH"
    );
}


int main(void)
{
    /*
     * Basic matching.
     */
    test("^hello$", "hello");
    test("^hello$", "hello!");

    /*
     * Exact repetition: {n}.
     */
    test("^[0-9]{4}$", "1234");
    test("^[0-9]{4}$", "123");
    test("^[0-9]{4}$", "12345");

    /*
     * Bounded repetition: {n,m}.
     */
    test("^[0-9]{2,4}$", "12");
    test("^[0-9]{2,4}$", "123");
    test("^[0-9]{2,4}$", "1234");
    test("^[0-9]{2,4}$", "12345");

    /*
     * Open-ended repetition: {n,}.
     */
    test("^a{2,}$", "aa");
    test("^a{2,}$", "aaaa");
    test("^a{2,}$", "a");

    /*
     * Zero or more: *.
     */
    test("^ab*c$", "ac");
    test("^ab*c$", "abc");
    test("^ab*c$", "abbbc");

    /*
     * One or more: +.
     */
    test("^ab+c$", "ac");
    test("^ab+c$", "abc");
    test("^ab+c$", "abbbc");

    /*
     * Zero or one: ?.
     */
    test("^colou?r$", "color");
    test("^colou?r$", "colour");
    test("^colou?r$", "colouur");

    /*
     * Alternation: |.
     */
    test("^(cat|dog)$", "cat");
    test("^(cat|dog)$", "dog");
    test("^(cat|dog)$", "bird");

    /*
     * Alternation without an explicit group.
     */
    test("cat|dog", "I have a cat");
    test("cat|dog", "I have a dog");
    test("cat|dog", "I have a bird");

    /*
     * Group repetition.
     */
    test("^(ab){3}$", "ababab");
    test("^(ab){3}$", "abab");
    test("^(ha)+$", "hahaha");

    /*
     * More complex expressions.
     */
    test(
        "^(ERROR|WARN): [0-9]{4}$",
        "ERROR: 1234"
    );

    test(
        "^(ERROR|WARN): [0-9]{4}$",
        "WARN: 9999"
    );

    test(
        "^(ERROR|WARN): [0-9]{4}$",
        "INFO: 1234"
    );

    /*
     * Character classes.
     */
    test("^[a-z]{3,6}$", "hello");
    test("^[A-Z][a-z]+$", "Hello");
    test(
        "^\\d{4}-\\d{2}-\\d{2}$",
        "2026-09-28"
    );

    /*
     * Word characters.
     */
    test("^\\w+$", "abc_123");
    test("^\\w+$", "abc-123");

    /*
     * Search for a matching substring.
     */
    test("[0-9]{4}", "abc1234xyz");
    test("(cat|dog)", "my dog is here");

    return 0;
}

#endif
